query:
-- Lister tous les terroirs existants
SELECT id, name, region FROM terroirs ORDER BY name;

-- Compter les plantes sans terroir (orphelines)
SELECT COUNT(*) as orphan_count FROM plants WHERE terroir_id IS NULL;

-- Lister les plantes orphelines avec leurs noms
SELECT id, name, scientific_name FROM plants WHERE terroir_id IS NULL ORDER BY name LIMIT 50;

